/** Minimal demo SCORM run-time for the two attributed sample packages. Not a conformance-certified LMS. */
export class ScormRuntime{
 constructor(attempt,course,{onChange=()=>{},onExit=()=>{},clock=()=>Date.now()}={}){this.attempt=attempt;this.course=course;this.onChange=onChange;this.onExit=onExit;this.clock=clock;this.initialized=false;this.terminated=false;this.error='0';this.start=0;this.version=course.version;this.is12=this.version==='1.2';this.api=this.is12?{LMSInitialize:a=>this.initialize(a),LMSFinish:a=>this.terminate(a),LMSGetValue:k=>this.get(k),LMSSetValue:(k,v)=>this.set(k,v),LMSCommit:a=>this.commit(a),LMSGetLastError:()=>this.error,LMSGetErrorString:c=>this.errorString(c),LMSGetDiagnostic:()=>this.error}:{Initialize:a=>this.initialize(a),Terminate:a=>this.terminate(a),GetValue:k=>this.get(k),SetValue:(k,v)=>this.set(k,v),Commit:a=>this.commit(a),GetLastError:()=>this.error,GetErrorString:c=>this.errorString(c),GetDiagnostic:()=>this.error};}
 fail(code){this.error=String(code);return 'false'}
 available(){if(!this.initialized||this.terminated){this.error=this.is12?'301':this.terminated?'133':'122';return false}return true}
 log(type,key='',value=''){const a=this.attempt;a.updatedAt=new Date(this.clock()).toISOString();a.events.push({id:crypto.randomUUID(),at:a.updatedAt,type,key,value:String(value)});if(a.events.length>600)a.events.splice(0,a.events.length-600);this.onChange(a,{type,key,value});}
 initialize(arg){if(arg!=='')return this.fail(201);if(this.initialized)return this.fail(this.is12?101:103);if(this.terminated)return this.fail(104);this.initialized=true;this.start=this.clock();this.attempt.sessions++;this.attempt.data[this.is12?'cmi.core.entry':'cmi.entry']=this.attempt.sessions>1?'resume':'ab-initio';this.error='0';this.log('initialize');return 'true'}
 count(prefix){const found=new Set();Object.keys(this.attempt.data).forEach(k=>{if(k.startsWith(prefix+'.')){const part=k.slice(prefix.length+1).split('.')[0];if(/^\d+$/.test(part))found.add(Number(part))}});return String(found.size?Math.max(...found)+1:0)}
 get(k){if(!this.available())return '';this.error='0';if(typeof k!=='string'){this.error='201';return ''}if(k.endsWith('._count'))return this.count(k.slice(0,-7));if(k.endsWith('._children'))return 'id,score,completion_status,success_status,progress_measure,description,learner_response,result,type';if(k.startsWith('adl.nav.request_valid'))return 'true';return String(this.attempt.data[k]??'')}
 set(k,v){if(!this.available())return 'false';if(typeof k!=='string'||!(/^(cmi\.|adl\.nav\.)/.test(k))||k.length>250)return this.fail(201);if(/\._count$|\._children$/.test(k))return this.fail(this.is12?402:404);if(['cmi.learner_id','cmi.learner_name','cmi.core.student_id','cmi.core.student_name','cmi.total_time','cmi.core.total_time','cmi.scaled_passing_score'].includes(k))return this.fail(this.is12?403:404);v=String(v);if(v.length>100000)return this.fail(405);if(['cmi.progress_measure','cmi.score.scaled'].includes(k)&&(!Number.isFinite(Number(v))||Number(v)>1||Number(v)<(k.endsWith('scaled')?-1:0)))return this.fail(407);this.error='0';const changed=this.attempt.data[k]!==v;this.attempt.data[k]=v;if(changed)this.log('set',k,v);return 'true'}
 commit(arg){if(!this.available())return 'false';if(arg!=='')return this.fail(201);this.error='0';this.attempt.commitCount++;this.log('commit');return 'true'}
 terminate(arg){if(arg!=='')return this.fail(201);if(!this.available())return 'false';this.attempt.elapsedMs+=Math.max(0,this.clock()-this.start);this.terminated=true;this.error='0';this.log('terminate');if(['exitAll','suspendAll','exit','suspend'].includes(this.attempt.data['adl.nav.request']))this.onExit();return 'true'}
 close(){if(this.initialized&&!this.terminated)this.terminate('')}
 errorString(code){return ({0:'No error',101:'General exception',103:'Already initialized',104:'Terminated',122:'Not initialized',133:'Terminated',201:'Invalid argument',301:'Not initialized',402:'Invalid set',403:'Read only',404:'Read only',405:'Invalid value',407:'Value out of range'})[code]||'Runtime error'}
}
